{"implementation":"def solve(case):
    def is_int(value):
        return isinstance(value, int) and not isinstance(value, bool)

    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "segments" not in case or "budget" not in case:
        raise ValueError("missing required field")
    segments = case["segments"]
    budget = case["budget"]
    if not isinstance(segments, list) or not is_int(budget):
        raise ValueError("invalid case fields")
    if budget < 0:
        raise ValueError("budget must be nonnegative")

    allocations = []
    names = []
    seen = set()
    total_minimum = 0
    total_capacity = 0
    for segment in segments:
        if not isinstance(segment, dict):
            raise ValueError("segment must be an object")
        for field in ("name", "importance", "minimum", "capacity"):
            if field not in segment:
                raise ValueError("missing segment field")
        name = segment["name"]
        importance = segment["importance"]
        minimum = segment["minimum"]
        capacity = segment["capacity"]
        if not isinstance(name, str) or not is_int(importance) or not is_int(minimum) or not is_int(capacity):
            raise ValueError("invalid segment field")
        if name in seen or importance < 0 or minimum < 0 or capacity < minimum:
            raise ValueError("invalid segment values")
        seen.add(name)
        names.append(name)
        allocations.append(minimum)
        total_minimum += minimum
        total_capacity += capacity

    if budget < total_minimum or budget > total_capacity:
        raise ValueError("infeasible budget")

    remaining = budget - total_minimum
    while remaining:
        best_index = -1
        best_priority = None
        for index, segment in enumerate(segments):
            if allocations[index] >= segment["capacity"]:
                continue
            priority = segment["importance"] / (allocations[index] + 1)
            if best_index < 0 or priority > best_priority:
                best_index = index
                best_priority = priority
        if best_index < 0:
            raise ValueError("infeasible budget")
        allocations[best_index] += 1
        remaining -= 1

    by_name = {name: allocations[index] for index, name in enumerate(names)}
    return {"allocations": allocations, "by_name": by_name, "total": sum(allocations)}"}
